from text_adventure_games import games, things, actions, blocks
from text_adventure_games.npc import make_hybrid_behavior, make_follow_behavior


def _carries_property(character, prop):
    """True iff `character` is carrying any item with `prop` set truthy, in
    ANY slot -- their hand inventory, what they're wearing, what they're
    wielding, or inside a carried container. The block checks for "do you
    have a sharp weapon on you?" don't care which slot it sits in, but
    iterating ``character.inventory`` alone misses worn/wielded items, so
    a player who ``wield sword``-ed before walking up to the castle would
    silently fail the dragon-reward check and get arrested."""
    if character is None:
        return False
    pools = (
        character.inventory,
        getattr(character, "worn", {}) or {},
        getattr(character, "wielded", {}) or {},
    )
    for pool in pools:
        for item in pool.values():
            if item.get_property(prop):
                return True
            # A container might be the thing carrying the property-bearing
            # item (e.g. a sack with the sword inside).
            for inner in (getattr(item, "contents", None) or {}).values():
                if inner.get_property(prop):
                    return True
    return False


class ActionCastleII(games.Game):
    def __init__(self, start_at, player, characters=None, custom_actions=None):
        super().__init__(start_at, player, characters, custom_actions)

    def is_won(self) -> bool:
        if self.game_over:
            return True
        for name, character in self.characters.items():
            if character.get_property("is_champion") == True:
                msg = "The king touches your shoulder with the flat of the sword's blade and pronounces you the new champion of Action Castle! THE END.".format(
                    name=character.name.title()
                )
                self.game_over = True
                self.game_over_description = msg
                self.parser.ok(msg)
                return True
        return False


