class Give_Axe_To_Smith(actions.Action):
    # Custom-action precedence intercepts the verb before the engine's GIVE
    # routes it. That lets us do something GiveResponse can't: mutate the
    # axe's *description* and *examine_text* (plain attributes, not engine
    # properties) so subsequent ``look`` / ``examine axe`` reflect the new
    # adjective. The smith never actually holds the axe -- we sharpen it
    # in place, which is what the player observes anyway.
    ACTION_NAME = "give axe to smith"
    ACTION_DESCRIPTION = "Have the smith sharpen your axe"
    ACTION_ALIASES = ["hand axe to smith"]
    PLAYER_CUSTOM = True

    def __init__(self, game, command, actor=None):
        super().__init__(game, actor=actor)
        self.character = self.acting_character(command)
        self.smith = self.game.characters.get("smith")
        self.axe = self.parser.match_item(
            "axe", self.parser.get_items_in_scope(self.character)
        )

    def check_preconditions(self) -> bool:
        if self.smith is None or self.smith.location is not self.character.location:
            self.parser.fail("The smith isn't here.")
            return False
        if not self.was_matched(self.axe, "You don't have an axe to sharpen."):
            return False
        if not self.is_in_inventory(self.character, self.axe):
            return False
        if self.axe.get_property("is_sharp"):
            self.parser.fail("The axe is already keen as a razor.")
            return False
        return True

    def apply_effects(self):
        self.parser.ok(
            "The smith mutters under his breath and sets to work at the "
            "grindstone. Sparks fly. After a moment he hands the axe back, "
            "its edge now keen and bright. You feel ready to face anything."
        )
        # Mark the blade sharp -- this is what the catfish block reads.
        self.axe.set_property("is_sharp", True)
        # Swap the adjective in both description fields so 'look' and
        # 'examine axe' reflect the new state.
        self.axe.description = "a freshly sharpened axe"
        self.axe.examine_text = (
            "The axe's edge is freshly honed and gleams in the light."
        )


