class Propose(actions.Action):
    ACTION_NAME = "propose"
    ACTION_DESCRIPTION = "Flavor response: propose"
    ACTION_ALIASES = ["marry"]
    PLAYER_CUSTOM = True

    def __init__(self, game, command, actor=None):
        super().__init__(game, actor=actor)
        self.character = self.acting_character(command)

    def check_preconditions(self) -> bool:
        if self.character.location.name != "Middle of the Pond":
            self.parser.ok(
                "You want to propose here?.. Maybe a more romantic location is in order."
            )
            return False
        # You can't propose empty-handed -- a proposal needs a ring. Without
        # one the action gracefully fails as ordinary narration (not a
        # `[blocked]` precondition error) so it reads like the world telling
        # you "you need something to offer," not like the parser couldn't
        # route the verb.
        if not _carries_property(self.character, "is_engagement_ring"):
            self.parser.ok(
                "You start to drop to one knee -- but your pockets are empty. "
                "A proposal without a ring is just a question."
            )
            return False
        return True

    def apply_effects(self):
        # With the ring in hand at the pond, propose ALWAYS closes the run.
        # The earlier version gated on Rosemary being co-located, but the
        # adjacency-based follow makes that unreliable: if she fell behind
        # while the player went off questing for the ring, the storybook
        # ending would silently downgrade to a regular betrothal. Treating
        # her as implied here ("a betrothed couple" -- she meets you on shore)
        # keeps the obvious win path actually winning. Game.is_won() reads
        # game_over, so this counts as a win.
        rosemary = self.game.characters.get("rosemary")
        ending = (
            "You produce the enormous diamond ring, and even the stars seem "
            "to pause. \"Oh -- it's beautiful!\" Rosemary's voice carries to "
            "you across the water as you row back. She slips the gem onto her "
            "finger and you are betrothed on the quiet water, far from any "
            "dragons, and live happily ever after. THE END."
        )
        self.parser.ok(ending)
        self.character.set_property("is_betrothed", True)
        self.character.set_property("is_married", True)
        if rosemary is not None:
            rosemary.set_property("is_married", True)
        self.game.game_over = True
        self.game.game_over_description = ending


