class Choose_Sword(actions.Action):
    ACTION_NAME = "choose sword"
    ACTION_DESCRIPTION = "Transform: choose sword"
    ACTION_ALIASES = []
    PLAYER_CUSTOM = True

    def __init__(self, game, command, actor=None):
        super().__init__(game, actor=actor)
        self.character = self.acting_character(command)
        self.item = self.parser.match_item(
            "sword", self.parser.get_items_in_scope(self.character)
        )

    def check_preconditions(self) -> bool:
        if not self.was_matched(self.item, "There's no sword here."):
            return False
        # The dragon doesn't offer a reward until the riddle has been
        # answered. We read this on the DRAGON, not the sword, because the
        # ``is_defeated`` flag lives on the dragon item (set by
        # Answer_Wise_Man). Checking the dragon also keeps the message
        # honest -- the sword isn't refusing you, the dragon hasn't said
        # take-your-pick yet.
        dragon = self.game.locations["Treasure Trove"].items.get("dragon")
        if dragon is None or not dragon.get_property("is_defeated"):
            self.parser.fail(
                "The dragon hasn't offered any reward yet. Best not to "
                "reach into the hoard uninvited."
            )
            return False
        if self.character.get_property("has_taken_reward"):
            self.parser.fail("You've already taken your reward. Best not to be greedy.")
            return False
        return True

    def apply_effects(self):
        self.character.set_property("has_taken_reward", True)
        self.parser.ok(
            f'"The sword of the fallen champion? A bold choice!" roars the dragon. "Now begone, and leave me to my slumber." You strap the sword to your waist, and the dragon goes back to sleep.'
        )
        # Hand the sword over directly -- the player doesn't need a
        # follow-up ``get sword`` to actually carry it. ``gettable`` stays
        # set so any oddball case (e.g. they drop it later and want to
        # pick it back up) still works.
        self.item.set_property("gettable", True)
        if self.item.location is not None:
            self.item.location.remove_item(self.item)
        self.character.accept_item(self.item)


