class Guards_Watch(actions.Action):
    ACTION_NAME = "guards watch"
    ACTION_DESCRIPTION = "NPC taunt: guards watch"
    ACTION_ALIASES = []
    PLAYER_CUSTOM = True
    NPC_ONLY = True

    def __init__(self, game, command, actor=None):
        super().__init__(game, actor=actor)
        self.character = self.acting_character(
            command, split_words="guards watch".split("|"), position="before"
        )
        self.target = self.parser.get_character(
            command,
            split_words=["guards watch"],
            position="after",
            exclude=self.character,
        )

    def check_preconditions(self) -> bool:
        if not self.at(self.character, self.target.location):
            return False
        if self.character.get_property("is_dead"):
            self.parser.fail(f"{self.character.name} has been banished.")
            return False
        return True

    def apply_effects(self):
        description = f"{self.character.name.capitalize()} watch {self.target.name} with cold suspicion."
        self.parser.npc_ok(description)


# ---- Custom Blocks ----


class Moat_Catfish_Block(blocks.Block):
    """Auto-generated property block (target='item'='catfish')."""

    def __init__(self, location, obstacle):
        super().__init__(
            "Your way is blocked",
            "As you enter the water, a monstrous catfish as big as a horse rears up and drags you away in its jaws. THE END.",
        )
        self.location = location
        self.obstacle = obstacle
        self.lethal = True

    def is_blocked(self, actor=None) -> bool:
        if not self.obstacle:
            return False
        if self.obstacle.name not in self.location.items:
            return False
        # Carrying a sharp blade in ANY slot (hand, wielded, container) lets
        # you survive the moat -- not just one held in your inventory dict.
        if actor is not None and _carries_property(actor, "is_sharp"):
            return False
        return True


class Moat_Tunnel_Block(blocks.Block):
    """Auto-generated property block (target='item'='walls')."""

    def __init__(self, location, obstacle):
        super().__init__(
            "Your way is blocked",
            "You see no way through the wall. There must be a hidden passage.",
        )
        self.location = location
        self.obstacle = obstacle

    def is_blocked(self, actor=None) -> bool:
        if not self.obstacle:
            return False
        if self.obstacle.name not in self.location.items:
            return False
        if not (not self.obstacle.get_property("tunnel_revealed")):
            return False
        return True


class Courtyard_Sword_Block(blocks.Block):
    """Auto-generated property block (target='character'='guards')."""

    def __init__(self, location, obstacle):
        super().__init__(
            "Your way is blocked",
            "The guards grab you by the arms. You are arrested for trespassing and locked in the dungeon. This is where you remain for the rest of your miserable days. THE END.",
        )
        self.location = location
        self.obstacle = obstacle
        self.lethal = True

    def is_blocked(self, actor=None) -> bool:
        if not self.obstacle:
            return False
        if self.obstacle.location is not self.location:
            return False
        # The dragon-reward sword earns safe passage no matter how the player
        # carries it -- wielded, worn at the hip, or in a carried pouch.
        # (The prior bug: a player who ``wield sword``-ed before climbing the
        # courtyard arch got arrested, because the check only looked in the
        # inventory dict.)
        if actor is not None and _carries_property(actor, "is_dragon_reward"):
            return False
        return True


# ---- NPC Behavior Factories ----


def make_guards_behavior():
    """Factory for the 'guards' character. Escalates over turns; state lives in a closure (matching the reference pattern)."""
    commands = [
        "guards guards watch {player}",
    ]
    fallback = "guards guards watch {player}"
    state = {"turns_present": 0}

    def behavior(character, game):
        player = game.player
        if player.location is not character.location:
            state["turns_present"] = 0
            return
        if character.get_property("emotional_state") != "watchful":
            return
        state["turns_present"] += 1
        idx = state["turns_present"] - 1
        if idx >= len(commands):
            if fallback:
                game.parser.parse_command(
                    fallback.format(player=player.name),
                    actor=character,
                )
            return
        cmd = commands[idx].format(player=player.name)
        game.parser.parse_command(cmd, actor=character)

    return behavior


